62	    /** The terms a claim of the person dated on the date is due by: the person's own, else those of their
63	     *  grade in force on the date, else the sheet's in force on the date. */
64	    private int termsOf(String sheetId, Person person, LocalDate date) {
65	        return person.getTerms() != null ? person.getTerms() : settings.terms(sheetId, person.gradeOn(date), date);
