68	    /** Add a claim to a person; a claim with no date is dated the sheet's today. */
69	    @Transactional
70	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
71	            String corrects) {
72	        Person person = person(sheetId, personId);
73	        LocalDate dated = dateOr(sheetId, date);
74	        refuseIfClosed(sheetId, dated);
75	        refuseIfRetired(person, dated);
76	        refuseIfNotCorrecting(sheetId, personId, amount, corrects);
77	        Rollup.Snapshot before = rollup.snapshot(sheetId);
78	        // The due-by is fixed now, from the terms in force on the claim's date.
79	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects,
80	                termsOf(sheetId, person, dated));
81	        // The sheet is locked (refuseIfClosed), so no other claim takes the same place.
82	        claim.setListed(claims.lastListed(sheetId) + 1);
83	        claim = claims.saveAndFlush(claim);
84	        logStatus(sheetId, user, person, claim);
85	        recordChange("CLAIM_ADDED", user, person, claim);
86	        rollup.recordChanges(user, before);
87	        return claim;
88	    }
