90	    /** Change a draft claim's amount, date and note; a blank date takes the sheet's today. A claim that
91	     *  is no longer a draft is refused: to change an open claim, void it and add a new one. */
92	    @Transactional
93	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
94	            String corrects) {
95	        Claim claim = claims.findForUpdate(id, sheetId)
96	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
97	        LocalDate dated = dateOr(sheetId, date);
98	        refuseIfClosed(sheetId, claim.getDate());
99	        refuseIfClosed(sheetId, dated);
100	        if (claim.getStatus() != ClaimStatus.DRAFT) {
101	            throw new ResponseStatusException(HttpStatus.CONFLICT,
102	                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
103	        }
104	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
105	        refuseIfNotCorrecting(sheetId, claim.getPersonId(), amount, corrects);
106	        Rollup.Snapshot before = rollup.snapshot(sheetId);
107	        claim.set(amount, dated, noteOf(note), corrects);
108	        Claim saved = claims.saveAndFlush(claim);
109	        recordChange("CLAIM_EDITED", user, person(sheetId, saved.getPersonId()), saved);
110	        rollup.recordChanges(user, before);
111	        return saved;
112	    }
