114	    /** Move a claim to a new status; a change its status does not allow is refused, as is settling
115	     *  by the user who opened the claim, and an action the sheet's permission matrix does not allow the
116	     *  user's role. A clerk's settling of a claim whose due is above the sheet's
117	     *  clerk limit leaves it PENDING for a steward to approve (a due of n/a is within any limit; a
118	     *  steward settles anything). */
119	    @Transactional
120	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
121	        Claim claim = claims.findForUpdate(id, sheetId)
122	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
123	        refuseIfClosed(sheetId, claim.getDate());
124	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
125	        if (voidingSettled) {
126	            refuseUnlessSettledVoidable(sheetId, user, claim);
127	        } else if (!claim.getStatus().canBecome(next)) {
128	            throw new ResponseStatusException(HttpStatus.CONFLICT,
129	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
130	        } else {
131	            settings.refuseUnlessPermitted(sheetId, user, ACTIONS.get(next),
132	                    "Your role may not " + ACTIONS.get(next) + " a claim on this sheet.");
133	        }
134	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
135	            throw new ResponseStatusException(HttpStatus.CONFLICT,
136	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then.");
137	        }
138	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
139	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
140	                    "The user who opened a claim cannot settle it.");
141	        }
142	        Person person = person(sheetId, claim.getPersonId());
143	        // Worked out while the claim is still open: settling freezes the due, its late charge included.
144	        BigDecimal dueNow = next == ClaimStatus.SETTLED ? due(sheetId, person, claim) : null;
145	        if (next == ClaimStatus.SETTLED) refuseIfUnproven(sheetId, claim, dueNow);
146	        if (next == ClaimStatus.SETTLED && isAboveClerkLimit(sheetId, user, dueNow)) next = ClaimStatus.PENDING;
147	        Rollup.Snapshot before = rollup.snapshot(sheetId);
148	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : claim.getNumber();
149	        claim.setStatus(next);
150	        if (next == ClaimStatus.OPEN) claim.setOpenedBy(user);
151	        // A voided claim keeps its number, which is never given to another claim.
152	        claim.setNumber(number);
153	        if (next == ClaimStatus.SETTLED) claim.setSettledDue(dueNow);
154	        logStatus(sheetId, user, person, claim);
155	        Claim saved = claims.saveAndFlush(claim);
156	        String event = EVENTS.get(next);
157	        if (next == ClaimStatus.SETTLED) {
158	            recordChange(event, user, person, saved, number, " due=" + text(saved.getSettledDue()));
159	            notifyWatchers(user, person, saved);
160	        } else if (voidingSettled) {
161	            recordChange(event, user, person, saved, number, " reversed=" + text(saved.getSettledDue()));
162	        } else {
163	            recordChange(event, user, person, saved, number, "");
164	        }
165	        rollup.recordChanges(user, before);
166	        return saved;
167	    }
