169	    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the
170	     *  claim counts in no total, is not overdue, cannot be settled and no statement binds it. Refused for
171	     *  a claim that is not OPEN, a date not after today, and a claim dated inside a closed period. */
172	    @Transactional
173	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
174	        Claim claim = claims.findForUpdate(id, sheetId)
175	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
176	        refuseIfClosed(sheetId, claim.getDate());
177	        if (claim.getStatus() != ClaimStatus.OPEN) {
178	            throw new ResponseStatusException(HttpStatus.CONFLICT,
179	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can.");
180	        }
181	        if (!until.isAfter(sheets.today(sheetId))) {
182	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
183	                    "A claim can only be deferred to a date after the sheet's today.");
184	        }
185	        Person person = person(sheetId, claim.getPersonId());
186	        Rollup.Snapshot before = rollup.snapshot(sheetId);
187	        claim.deferUntil(until);
188	        Claim saved = claims.saveAndFlush(claim);
189	        recordChange("CLAIM_DEFERRED", user, person, saved, saved.getNumber(), " until=" + until);
190	        rollup.recordChanges(user, before);
191	        return saved;
192	    }
