194	    /** Split an amount (more than 0.00 and less than the claim's amount) off an OPEN claim into a new
195	     *  OPEN claim of the same person, date and note, given the next number, opened by the user and due
196	     *  by the terms in force on the date; the claim keeps the rest and loses any figure a statement bound
197	     *  it to. Refused for a claim that is not OPEN (a PENDING one included), a deferred claim, and a claim
198	     *  dated inside a closed period. */
199	    @Transactional
200	    public Split split(String sheetId, String user, long id, BigDecimal part) {
201	        Claim claim = claims.findForUpdate(id, sheetId)
202	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
203	        refuseIfClosed(sheetId, claim.getDate());
204	        if (claim.getStatus() != ClaimStatus.OPEN) {
205	            throw new ResponseStatusException(HttpStatus.CONFLICT,
206	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can.");
207	        }
208	        if (claim.isDeferredOn(sheets.today(sheetId))) {
209	            throw new ResponseStatusException(HttpStatus.CONFLICT,
210	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be split.");
211	        }
212	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
213	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
214	                    "The amount split off must be more than 0.00 and less than the claim's amount.");
215	        }
216	        Person person = person(sheetId, claim.getPersonId());
217	        Rollup.Snapshot before = rollup.snapshot(sheetId);
218	        String number = nextNumber(sheetId, claim);
219	        // The due-by is fixed now, from the terms in force on the claim's date.
220	        Claim split = claim.splitOff(part, number, user, termsOf(sheetId, person, claim.getDate()));
221	        split.setListed(claims.lastListed(sheetId) + 1);
222	        Claim saved = claims.saveAndFlush(claim);
223	        split = claims.saveAndFlush(split);
224	        logStatus(sheetId, user, person, split);
225	        recordChange("CLAIM_SPLIT", user, person, saved, saved.getNumber(), " into=" + number);
226	        recordChange("CLAIM_OPENED", user, person, split);
227	        rollup.recordChanges(user, before);
228	        return new Split(saved, split);
229	    }
