235	    /** Re-date an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure a statement bound
236	     *  it to stays bound; its period follows the new date, and while the sheet's period numbering is in
237	     *  force a claim whose period changes takes the next number of its new period (or of claims in no
238	     *  period), its old number never given again. Refused unless the user is a steward of the sheet, and
239	     *  for a claim that is not OPEN or PENDING, a claim dated inside a closed period, a new date inside
240	     *  one, and a new date after its person's retirement. */
241	    @Transactional
242	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
243	        Claim claim = claims.findForUpdate(id, sheetId)
244	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
245	        refuseIfClosed(sheetId, claim.getDate());
246	        refuseIfClosed(sheetId, date);
247	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
248	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-dates a claim.");
249	        }
250	        if (!claim.getStatus().isOpen()) {
251	            throw new ResponseStatusException(HttpStatus.CONFLICT,
252	                    "A " + claim.getStatus() + " claim cannot be re-dated; only an OPEN or PENDING one can.");
253	        }
254	        Person person = person(sheetId, claim.getPersonId());
255	        refuseIfRetired(person, date);
256	        Rollup.Snapshot before = rollup.snapshot(sheetId);
257	        LocalDate old = claim.getDate();
258	        Period oldPeriod = periodOf(sheetId, old);
259	        Period newPeriod = periodOf(sheetId, date);
260	        claim.redate(date);
261	        boolean samePeriod = oldPeriod == null ? newPeriod == null
262	                : newPeriod != null && oldPeriod.getId().equals(newPeriod.getId());
263	        if (!samePeriod && isPeriodNumbering(sheetId)) claim.setNumber(nextNumber(sheetId, claim));
264	        Claim saved = claims.saveAndFlush(claim);
265	        recordChange("CLAIM_REDATED", user, person, saved, saved.getNumber(), " old=" + old + " new=" + date);
266	        rollup.recordChanges(user, before);
267	        return saved;
268	    }
269	
270	    /** Raise a claim's proofs count by one. Refused for a SETTLED or VOID claim, and a claim dated
271	     *  inside a closed period. No figure moves. */
272	    @Transactional
273	    public Claim addProof(String sheetId, String user, long id) {
274	        Claim claim = claims.findForUpdate(id, sheetId)
275	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
276	        refuseIfClosed(sheetId, claim.getDate());
277	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
278	            throw new ResponseStatusException(HttpStatus.CONFLICT,
279	                    "A " + claim.getStatus() + " claim cannot have a proof added.");
280	        }
281	        Person person = person(sheetId, claim.getPersonId());
282	        claim.addProof();
283	        Claim saved = claims.saveAndFlush(claim);
284	        recordChange("CLAIM_PROOF_ADDED", user, person, saved, saved.getNumber(), " proofs=" + saved.getProofs());
285	        return saved;
286	    }
287	
288	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet, as their newest claim. It
289	     *  keeps its number and date and loses any figure a statement bound it to (it is live again until
290	     *  its new person's next statement). Refused unless the sheet's permission matrix allows the user's
291	     *  role to reassign (by default, a steward), and for a
292	     *  settled or voided claim, a claim dated inside a closed period, a move to the claim's own person,
293	     *  or to a person retired by the claim's date. */
294	    @Transactional
295	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
296	        Claim claim = claims.findForUpdate(id, sheetId)
297	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
298	        refuseIfClosed(sheetId, claim.getDate());
299	        settings.refuseUnlessPermitted(sheetId, user, "reassign",
300	                "Your role may not move a claim to another person on this sheet.");
301	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
302	            throw new ResponseStatusException(HttpStatus.CONFLICT,
303	                    "A " + claim.getStatus() + " claim cannot be moved to another person.");
304	        }
305	        Person from = person(sheetId, claim.getPersonId());
306	        Person to = person(sheetId, toPersonId);
307	        if (from.getId().equals(to.getId())) {
308	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
309	        }
310	        refuseIfRetired(to, claim.getDate());
311	        Rollup.Snapshot before = rollup.snapshot(sheetId);
312	        claim.moveTo(to.getId(), claims.lastListed(sheetId) + 1);
313	        Claim saved = claims.saveAndFlush(claim);
314	        recordChange("CLAIM_REASSIGNED", user, to, saved, saved.getNumber(),
315	                " from=" + from.getName() + " to=" + to.getName());
316	        rollup.recordChanges(user, before);
317	        return saved;
318	    }
319	
320	    /** Approve a PENDING claim: it is SETTLED, its due (its live figure and any late charge) frozen
321	     *  now. Refused unless the user is a steward of the sheet other than the one who opened it. */
322	    @Transactional
323	    public Claim approve(String sheetId, String user, long id) {
324	        Claim claim = pending(sheetId, user, id);
325	        if (user.equals(claim.getOpenedBy())) {
326	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
327	                    "The user who opened a claim cannot approve it.");
328	        }
329	        Person person = person(sheetId, claim.getPersonId());
330	        BigDecimal dueNow = due(sheetId, person, claim);
331	        refuseIfUnproven(sheetId, claim, dueNow);
332	        Rollup.Snapshot before = rollup.snapshot(sheetId);
333	        claim.setStatus(ClaimStatus.SETTLED);
334	        claim.setSettledDue(dueNow);
335	        logStatus(sheetId, user, person, claim);
336	        Claim saved = claims.saveAndFlush(claim);
337	        recordChange("CLAIM_APPROVED", user, person, saved, saved.getNumber(), " due=" + text(saved.getSettledDue()));
338	        notifyWatchers(user, person, saved);
339	        rollup.recordChanges(user, before);
340	        return saved;
341	    }
342	
343	    /** Re-settle a SETTLED claim: its due is frozen again at what it would be today as an open claim
344	     *  bound by no statement (today's rates, grades, floor and late charge). Refused unless the user is
345	     *  a steward of the sheet, and for a claim that is not SETTLED or is dated inside a closed period. */
346	    @Transactional
347	    public Claim resettle(String sheetId, String user, long id) {
348	        Claim claim = claims.findForUpdate(id, sheetId)
349	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
350	        refuseIfClosed(sheetId, claim.getDate());
351	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
352	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
353	        }
354	        if (claim.getStatus() != ClaimStatus.SETTLED) {
355	            throw new ResponseStatusException(HttpStatus.CONFLICT,
356	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
357	        }
358	        Person person = person(sheetId, claim.getPersonId());
359	        BigDecimal old = claim.getSettledDue();
360	        BigDecimal dueNow = LateCharge.dueAsOpen(claim, dueNow(sheetId, person, claim),
361	                settings.floor(sheetId, claim.getDate()), sheets.today(sheetId),
362	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
363	        Rollup.Snapshot before = rollup.snapshot(sheetId);
364	        claim.setSettledDue(dueNow);
365	        logStatus(sheetId, user, person, claim);
366	        Claim saved = claims.saveAndFlush(claim);
367	        recordChange("CLAIM_RESETTLED", user, person, saved, saved.getNumber(),
368	                " old=" + text(old) + " new=" + text(saved.getSettledDue()));
369	        notifyWatchers(user, person, saved);
370	        rollup.recordChanges(user, before);
371	        return saved;
372	    }
373	
374	    /** Reject a PENDING claim for a reason: it is OPEN again, bound again by its person's last
375	     *  statement if that statement bound it. Refused unless the user is a steward of the sheet. */
376	    @Transactional
377	    public Claim reject(String sheetId, String user, long id, String reason) {
378	        Claim claim = pending(sheetId, user, id);
379	        Person person = person(sheetId, claim.getPersonId());
380	        Rollup.Snapshot before = rollup.snapshot(sheetId);
381	        claim.setStatus(ClaimStatus.OPEN);
382	        logStatus(sheetId, user, person, claim);
383	        Claim saved = claims.saveAndFlush(claim);
384	        recordChange("CLAIM_REJECTED", user, person, saved, saved.getNumber(), " reason=" + reason);
385	        rollup.recordChanges(user, before);
386	        return saved;
387	    }
388	
389	    /** The PENDING claim a steward approves or rejects, locked; refused when it is not PENDING, is
390	     *  dated inside a closed period, or the user is not a steward of the sheet. */
391	    private Claim pending(String sheetId, String user, long id) {
392	        Claim claim = claims.findForUpdate(id, sheetId)
393	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
394	        refuseIfClosed(sheetId, claim.getDate());
395	        if (claim.getStatus() != ClaimStatus.PENDING) {
396	            throw new ResponseStatusException(HttpStatus.CONFLICT,
397	                    "A " + claim.getStatus() + " claim is not waiting for approval.");
398	        }
399	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
400	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
401	        }
402	        return claim;
403	    }
404	
405	    /** How many days after its settlement a steward may still void a SETTLED claim. */
406	    private static final int VOID_SETTLED_DAYS = 7;
407	
408	    /** Refuse voiding a SETTLED claim unless the user is a steward of the sheet and the sheet's today is
409	     *  within {@value #VOID_SETTLED_DAYS} days of the claim's settlement, as its status log records it. */
410	    private void refuseUnlessSettledVoidable(String sheetId, String user, Claim claim) {
411	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
412	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a settled claim.");
413	        }
414	        LocalDate settledOn = claim.settledOn();
415	        LocalDate today = sheets.today(sheetId);
416	        if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
417	            throw new ResponseStatusException(HttpStatus.CONFLICT,
418	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement.");
419	        }
420	    }
421	
422	    /** The permission matrix's action for each status a claim is moved to by opening, settling or voiding it. */
423	    private static final Map<ClaimStatus, String> ACTIONS = Map.of(
424	            ClaimStatus.OPEN, "open", ClaimStatus.SETTLED, "settle", ClaimStatus.PENDING, "settle",
425	            ClaimStatus.VOID, "void");
426	
427	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
428	            ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.PENDING, "CLAIM_PENDING",
429	            ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.VOID, "CLAIM_VOIDED");
430	
431	    private static String text(BigDecimal due) {
432	        return due == null ? "n/a" : due.toPlainString();
433	    }
434	
435	    /** The number a claim takes as it is opened: while the sheet's period numbering is in force (its
436	     *  today on or after the setting's date), the next of the claim's period, <period name>-<n>, or of
437	     *  claims in no period, X-<n>; otherwise the sheet's next sheet-wide number. */
438	    private String nextNumber(String sheetId, Claim claim) {
439	        if (!isPeriodNumbering(sheetId)) {
440	            return Integer.toString(sheets.nextClaimNumber(sheetId));
441	        }
442	        Period period = periodOf(sheetId, claim.getDate());
443	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
444	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
445	    }
446	
447	    /** Whether the sheet's period numbering is in force: its today on or after the setting's date. */
448	    private boolean isPeriodNumbering(String sheetId) {
449	        LocalDate from = settings.periodNumberingFrom(sheetId);
450	        return from != null && !sheets.today(sheetId).isBefore(from);
451	    }
452	
453	    /** The sheet's period whose dates contain the date; null when none does. */
454	    private Period periodOf(String sheetId, LocalDate date) {
455	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
456	                .filter((p) -> p.contains(date)).findFirst().orElse(null);
457	    }
458	
459	    /** Refuse settling or approving a claim with no proofs whose due is above the sheet's proof threshold
460	     *  in force on the claim's date (a due of n/a, or no threshold, needs none). */
461	    private void refuseIfUnproven(String sheetId, Claim claim, BigDecimal due) {
462	        if (due == null || claim.getProofs() > 0) return;
463	        BigDecimal threshold = settings.proofThreshold(sheetId, claim.getDate());
464	        if (threshold != null && due.compareTo(threshold) > 0) {
465	            throw new ResponseStatusException(HttpStatus.CONFLICT,
466	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
467	                            + "; add a proof before it is settled.");
468	        }
469	    }
470	
471	    /** Whether the user is a clerk settling a claim whose due is above the sheet's clerk limit. */
472	    private boolean isAboveClerkLimit(String sheetId, String user, BigDecimal due) {
473	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
474	        BigDecimal limit = settings.clerkLimit(sheetId);
475	        return limit != null && due.compareTo(limit) > 0;
476	    }
477	
478	    /** Refuse a change to a claim dated inside a closed period. The sheet is locked first, as closing
479	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
480	    private void refuseIfClosed(String sheetId, LocalDate date) {
481	        sheetRows.findForUpdate(sheetId);
482	        if (periods.isClosedOn(sheetId, date)) {
483	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is dated inside a closed period.");
484	        }
485	    }
486	
487	    /** Refuse a correction (a negative amount) unless it names, by number, a settled claim of the same person. */
488	    private void refuseIfNotCorrecting(String sheetId, long personId, BigDecimal amount, String corrects) {
489	        if (amount.signum() >= 0) return;
490	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
491	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).isPresent();
492	        if (!settled) {
493	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
494	                    "A negative amount must name, by number, a settled claim of the same person that it corrects.");
495	        }
496	    }
497	
498	    /** Refuse a claim dated after its person's retirement date. */
499	    private static void refuseIfRetired(Person person, LocalDate date) {
500	        if (person.isRetiredOn(date)) {
501	            throw new ResponseStatusException(HttpStatus.CONFLICT,
502	                    "The claim is dated after " + person.getName() + " retired.");
503	        }
504	    }
505	
506	    private Person person(String sheetId, long personId) {
507	        return people.findByIdAndSheetId(personId, sheetId)
508	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
509	    }
510	
511	    /** What is due on the claim now: the due fixed when it was settled, else the greater of the floor in
512	     *  force on its date and its figure with the late charge on top while it is open and overdue (the charge
513	     *  is never bound by a statement; a correction has no floor); null when the figure is n/a. */
514	    public BigDecimal due(String sheetId, Person person, Claim claim) {
515	        return LateCharge.dueOf(claim, figure(sheetId, person, claim), settings.floor(sheetId, claim.getDate()),
516	                sheets.today(sheetId),
517	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
518	    }
519	
520	    /** The figure under the claim's due, before any late charge and floor: the due fixed when it was settled, else the figure
521	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
522	     *  null when that is n/a. */
523	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
524	        if (claim.getSettledDue() != null) return claim.getSettledDue();
525	        if (claim.isBound()) return claim.getStatedDue();
526	        return dueNow(sheetId, person, claim);
527	    }
528	
529	    /** The claim's rate figure now: at the rate in force on the claim's date of its person's grade in
530	     *  force on that date, rounded as the claim's {@link Rounding} decides, before any late charge and
531	     *  floor; null when no rate of the grade applies by then. */
532	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
533	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
534	        if (rate == null) return null;
535	        return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
536	                rounding(sheetId, claim));
537	    }
538	
539	    /** How the claim's live figures round under the sheet's policy date: by the date of the claim a
540	     *  correction corrects, else by its own. */
541	    private RoundingMode rounding(String sheetId, Claim claim) {
542	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
543	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
544	                : null;
545	        return Rounding.of(Rounding.dateOf(claim, corrected),
546	                Rounding.policyDate(settings.policyDate(sheetId), sheets.today(sheetId)));
547	    }
548	
549	    /** Log the status the claim has just taken, with its due as worked out now. */
550	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
551	        claim.logStatus(user, sheets.today(sheetId), due(sheetId, person, claim));
552	    }
553	
554	    private void recordChange(String event, String user, Person person, Claim claim) {
555	        recordChange(event, user, person, claim, claim.getNumber(), "");
556	    }
557	
558	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
559	    private void recordChange(String event, String user, Person person, Claim claim, String number, String extra) {
560	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
561	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
562	                + (number == null ? "" : " number=" + number) + extra);
563	    }
564	
565	    /** Tell each user watching the person, in the order they started watching, that the claim was settled. */
566	    private void notifyWatchers(String user, Person person, Claim claim) {
567	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
568	            audit.recordOnCommit("NOTIFY sheet=" + claim.getSheetId() + " by=" + user + " user=" + watch.getUserName()
569	                    + " person=" + person.getName() + " number=" + claim.getNumber());
570	        }
571	    }
572	
573	    private LocalDate dateOr(String sheetId, LocalDate date) {
574	        return date != null ? date : sheets.today(sheetId);
575	    }
576	
577	    private static String noteOf(String note) {
578	        return note == null ? "" : note.trim();
579	    }
580	}
