1	import { Component, inject, input, output, signal } from '@angular/core';
2	import { HttpErrorResponse } from '@angular/common/http';
3	import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
4	import { Session } from '../../core/session';
5	import { PeriodView, periodOf } from '../periods/periods-api';
6	import { GradeView, gradeOn } from '../people/people-api';
7	import { RateView } from '../rates/rates-api';
8	import { SheetFloor } from '../settings/sheet-floor';
9	import { SheetLatePct } from '../settings/sheet-late-pct';
10	import { SheetPolicyDate } from '../settings/sheet-policy-date';
11	import { CLAIM_AMOUNT, CLAIM_NUMBER, ClaimAction, ClaimView, ClaimsApi, SplitView, claimOwedCents, isDeferred, isOverdue, money } from './claims-api';
12	
13	const DATE = /^\d{4}-\d{2}-\d{2}$/;
14	const PAST: Record<ClaimAction, string> = { open: 'opened', settle: 'settled', void: 'voided', approve: 'approved', reject: 'rejected', resettle: 're-settled' };
15	
16	// One person's claims, newest first, with one form to add a claim or edit one.
17	@Component({
18	  selector: 'app-person-claims',
19	  imports: [ReactiveFormsModule],
20	  template: `
21	    <form [formGroup]="form" (ngSubmit)="submit()"
22	      [attr.aria-label]="(editingId() === null ? 'Add a claim for ' : 'Edit a claim of ') + personName()">
23	      <label [for]="fieldId('amount')">Amount</label>
24	      <input [id]="fieldId('amount')" data-testid="claim-form-amount" formControlName="amount" inputmode="decimal" />
25	      <label [for]="fieldId('date')">Date</label>
26	      <input [id]="fieldId('date')" type="date" data-testid="claim-form-date" formControlName="date" />
27	      <label [for]="fieldId('note')">Note</label>
28	      <input [id]="fieldId('note')" data-testid="claim-form-note" formControlName="note" />
29	      <label [for]="fieldId('corrects')">Corrects claim no.</label>
30	      <input [id]="fieldId('corrects')" data-testid="claim-form-corrects" formControlName="corrects" />
31	      <button type="submit" data-testid="claim-form-submit" [disabled]="saving()">
32	        {{ editingId() === null ? 'Add claim' : 'Save claim' }}
33	      </button>
34	      @if (error()) {
35	        <p role="alert" data-testid="claim-form-error">{{ error() }}</p>
36	      }
37	    </form>
38	    <ul [attr.aria-label]="'Claims of ' + personName()">
39	      @for (c of claims(); track c.id) {
40	        <li [attr.data-testid]="'claim-row-' + c.id">
41	          <input type="checkbox" data-testid="claim-select" [checked]="selected().has(c.id)"
42	            (change)="selectedChange.emit({ id: c.id, on: $any($event.target).checked })"
43	            [attr.aria-label]="'Select claim of ' + c.amount + ' on ' + c.date" />
44	          <span>No. <span data-testid="claim-number">{{ c.number ?? '' }}</span></span>
45	          <span data-testid="claim-amount">{{ c.amount }}</span>
46	          <span data-testid="claim-date">{{ c.date }}</span>
47	          <span data-testid="claim-note">{{ c.note }}</span>
48	          <span>Corrects <span data-testid="claim-corrects">{{ c.corrects ?? '' }}</span></span>
49	          <span>Due <span data-testid="claim-due">{{ due(c) }}</span></span>
50	          <span data-testid="claim-status">{{ c.status }}</span>
51	          <span>Opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span></span>
52	          <span>Stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span></span>
53	          <span>Period <span data-testid="claim-period">{{ periodName(c) }}</span></span>
54	          <span>Due by <span data-testid="claim-due-by">{{ c.dueBy }}</span></span>
55	          <span>Overdue <span data-testid="claim-overdue">{{ overdue(c) ? 'yes' : 'no' }}</span></span>
56	          <span>Deferred <span data-testid="claim-deferred">{{ deferred(c) ? 'yes' : 'no' }}</span></span>
57	          <span>Deferred until <span data-testid="claim-deferred-until">{{ c.deferredUntil ?? '' }}</span></span>
58	          <span>Proofs <span data-testid="claim-proofs">{{ c.proofs }}</span></span>
59	          <span>Split from <span data-testid="claim-split-from">{{ c.splitFrom ?? '' }}</span></span>
60	          <ol [attr.aria-label]="'Status log of claim of ' + c.amount + ' on ' + c.date">
61	            @for (line of c.log; track $index) {
62	              <li data-testid="claim-log-line">{{ line.status }} by {{ line.by }} on {{ line.on }} due={{ line.due ?? 'n/a' }}</li>
63	            }
64	          </ol>
65	          <button type="button" data-testid="claim-open" (click)="act(c, 'open')"
66	            [attr.aria-label]="'Open claim of ' + c.amount + ' on ' + c.date">Open</button>
67	          <button type="button" data-testid="claim-settle" (click)="act(c, 'settle')"
68	            [attr.aria-label]="'Settle claim of ' + c.amount + ' on ' + c.date">Settle</button>
69	          <button type="button" data-testid="claim-approve" (click)="act(c, 'approve')"
70	            [attr.aria-label]="'Approve claim of ' + c.amount + ' on ' + c.date">Approve</button>
71	          <button type="button" data-testid="claim-resettle" (click)="act(c, 'resettle')"
72	            [attr.aria-label]="'Re-settle claim of ' + c.amount + ' on ' + c.date">Re-settle</button>
73	          <label [for]="'claim-reject-reason-' + c.id">Reject reason</label>
74	          <input #rejectReason [id]="'claim-reject-reason-' + c.id" data-testid="claim-reject-reason" />
75	          <button type="button" data-testid="claim-reject" (click)="act(c, 'reject', rejectReason.value)"
76	            [attr.aria-label]="'Reject claim of ' + c.amount + ' on ' + c.date">Reject</button>
77	          <button type="button" data-testid="claim-void" (click)="act(c, 'void')"
78	            [attr.aria-label]="'Void claim of ' + c.amount + ' on ' + c.date">Void</button>
79	          <label [for]="'claim-defer-date-' + c.id">Defer until</label>
80	          <input #deferDate type="date" [id]="'claim-defer-date-' + c.id" data-testid="claim-defer-date" />
81	          <button type="button" data-testid="claim-defer" (click)="defer(c, deferDate.value)"
82	            [attr.aria-label]="'Defer claim of ' + c.amount + ' on ' + c.date">Defer</button>
83	          <label [for]="'claim-date-new-' + c.id">Re-date to</label>
84	          <input #newDate type="date" [id]="'claim-date-new-' + c.id" data-testid="claim-date-new" />
85	          <button type="button" data-testid="claim-redate" (click)="redate(c, newDate.value)"
86	            [attr.aria-label]="'Re-date claim of ' + c.amount + ' on ' + c.date">Re-date</button>
87	          <button type="button" data-testid="claim-proof" (click)="addProof(c)"
88	            [attr.aria-label]="'Add a proof to claim of ' + c.amount + ' on ' + c.date">Add proof</button>
89	          <label [for]="'claim-split-amount-' + c.id">Split off</label>
90	          <input #splitAmount [id]="'claim-split-amount-' + c.id" data-testid="claim-split-amount" inputmode="decimal" />
91	          <button type="button" data-testid="claim-split" (click)="splitClaim(c, splitAmount.value)"
92	            [attr.aria-label]="'Split claim of ' + c.amount + ' on ' + c.date">Split</button>
93	          <label [for]="'claim-reassign-to-' + c.id">Move to</label>
94	          <select #reassignTo [id]="'claim-reassign-to-' + c.id" data-testid="claim-reassign-to">
95	            <option value="">Choose a person</option>
96	            @for (o of people(); track o.id) {
97	              @if (o.id !== personId()) {
98	                <option [value]="o.id">{{ o.name }}</option>
99	              }
100	            }
101	          </select>
102	          <button type="button" data-testid="claim-reassign" (click)="reassign(c, reassignTo.value)"
103	            [attr.aria-label]="'Move claim of ' + c.amount + ' on ' + c.date + ' to another person'">Move</button>
104	          <button type="button" data-testid="claim-edit" (click)="edit(c)"
105	            [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
106	          @if (editingId() === c.id) {
107	            <button type="button" data-testid="claim-cancel" (click)="cancel()">Cancel</button>
108	          }
109	          @if (claimError()?.id === c.id) {
110	            <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
111	          }
112	        </li>
113	      }
114	    </ul>
115	  `,
116	})
117	export class PersonClaims {
118	  private readonly session = inject(Session);
119	  private readonly api = inject(ClaimsApi);
120	  private readonly floor = inject(SheetFloor);
121	  private readonly latePct = inject(SheetLatePct);
122	  private readonly policyDate = inject(SheetPolicyDate);
123	
124	  readonly personId = input.required<number>();
125	  readonly personName = input.required<string>();
126	  /** The person's claims, newest first. */
127	  readonly claims = input.required<ClaimView[]>();
128	  /** Everyone on the sheet, whom a claim can be moved to. */
129	  readonly people = input.required<readonly { id: number; name: string }[]>();
130	  /** The sheet's rates, whatever their grades and from-dates. */
131	  readonly rates = input.required<RateView[]>();
132	  /** The person's grades, each from its from-date. */
133	  readonly grades = input.required<GradeView[]>();
134	  /** The sheet's periods in date order. */
135	  readonly periods = input.required<PeriodView[]>();
136	  /** The ids of the claims selected on the sheet. */
137	  readonly selected = input.required<ReadonlySet<number>>();
138	  /** A claim's checkbox ticked or cleared. */
139	  readonly selectedChange = output<{ id: number; on: boolean }>();
140	  readonly added = output<ClaimView>();
141	  readonly saved = output<ClaimView>();
142	  /** A claim whose status changed. */
143	  readonly changed = output<ClaimView>();
144	  /** A claim moved to another person. */
145	  readonly reassigned = output<ClaimView>();
146	  /** A claim split in two. */
147	  readonly split = output<SplitView>();
148	
149	  protected readonly amount = new FormControl('', { nonNullable: true });
150	  protected readonly date = new FormControl('', { nonNullable: true });
151	  protected readonly note = new FormControl('', { nonNullable: true });
152	  protected readonly corrects = new FormControl('', { nonNullable: true });
153	  protected readonly form = new FormGroup({ amount: this.amount, date: this.date, note: this.note, corrects: this.corrects });
154	
155	  protected readonly editingId = signal<number | null>(null);
156	  protected readonly saving = signal(false);
157	  protected readonly error = signal('');
158	  /** The refusal of the last action taken on a claim's row, shown on that row. */
159	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
160	
161	  constructor() {
162	    this.form.valueChanges.subscribe(() => {
163	      this.error.set('');
164	      // A refused save shown on the claim being edited belongs to the form too.
165	      if (this.editingId() !== null && this.claimError()?.id === this.editingId()) this.claimError.set(null);
166	    });
167	  }
168	
169	  /** What is due on the claim: the figure fixed when it was settled, else the figure its person's
170	   *  last statement bound it to, else at the rate in force on the claim's date of the person's grade
171	   *  in force on that date, and at least the sheet's floor, or n/a when the claim is dated before every rate of the grade;
172	   *  an open overdue claim has its late charge on top. */
173	  protected due(claim: ClaimView): string {
174	    const grade = gradeOn(this.grades(), claim.date);
175	    const due = claimOwedCents(claim, this.rates().filter((r) => r.grade === grade), this.floor.centsOn(claim.date),
176	      { today: this.session.sheet()?.today, latePct: (date: string) => this.latePct.pctOn(date),
177	        policyDate: this.policyDate.date() ?? this.session.sheet()?.today }, this.claims());
178	    return due === null ? 'n/a' : money(due);
179	  }
180	
181	  /** Whether the claim is open and its due-by is before the sheet's today. */
182	  protected overdue(claim: ClaimView): boolean {
183	    return isOverdue(claim, this.session.sheet()?.today);
184	  }
185	
186	  /** Whether the claim is OPEN and deferred until a date the sheet's today has not reached. */
187	  protected deferred(claim: ClaimView): boolean {
188	    return isDeferred(claim, this.session.sheet()?.today);
189	  }
190	
191	  /** The name of the period whose dates contain the claim's date, or blank when none does. */
192	  protected periodName(claim: ClaimView): string {
193	    return periodOf(this.periods(), claim.date)?.name ?? '';
194	  }
195	
196	  private inClosedPeriod(date: string): boolean {
197	    return date !== '' && (periodOf(this.periods(), date)?.closed ?? false);
198	  }
199	
200	  protected fieldId(field: string): string {
201	    return `claim-form-${field}-${this.personId()}`;
202	  }
203	
204	  private reset(): void {
205	    this.editingId.set(null);
206	    this.error.set('');
207	    this.form.reset({ amount: '', date: '', note: '', corrects: '' }, { emitEvent: false });
208	  }
209	
210	  protected edit(claim: ClaimView): void {
211	    this.claimError.set(null);
212	    this.editingId.set(claim.id);
213	    this.error.set('');
214	    this.form.setValue({ amount: claim.amount, date: claim.date, note: claim.note, corrects: claim.corrects ?? '' },
215	      { emitEvent: false });
216	  }
217	
218	  /** Open, settle, void, approve, reject (for a reason) or re-settle a claim; the store refuses a change its
219	   *  status does not allow. A clerk's settling above the clerk limit leaves the claim PENDING. */
220	  protected async act(claim: ClaimView, action: ClaimAction, reason = ''): Promise<void> {
221	    const sheet = this.session.sheet();
222	    if (!sheet) return;
223	    this.claimError.set(null);
224	    if (action === 'reject' && reason.trim() === '') {
225	      this.claimError.set({ id: claim.id, message: 'Type a reason to reject this claim.' });
226	      return;
227	    }
228	    try {
229	      const changed = await this.api.act(sheet.id, claim.id, action, reason.trim());
230	      if (this.session.sheet()?.id === sheet.id) this.changed.emit(changed);
231	    } catch (e) {
232	      if (this.session.sheet()?.id === sheet.id) {
233	        const forbidden = e instanceof HttpErrorResponse && e.status === 403;
234	        const message = forbidden && (action === 'approve' || action === 'reject')
235	          ? `Only a steward who did not open this claim can ${action} it.`
236	          : forbidden && action === 'resettle'
237	          ? 'Only a steward can re-settle this claim.'
238	          : forbidden && action === 'void' && claim.status === 'SETTLED'
239	          ? 'Only a steward can void a settled claim.'
240	          : forbidden && action === 'settle' && claim.openedBy === this.session.user()
241	          ? 'You opened this claim, so someone else must settle it.'
242	          : forbidden
243	          ? `Your role may not ${action} a claim on this sheet.`
244	          : periodOf(this.periods(), claim.date)?.closed
245	            ? `This claim is dated inside a closed period, so it cannot be ${PAST[action]}.`
246	          : action === 'settle' && this.deferred(claim)
247	            ? `This claim is deferred until ${claim.deferredUntil}, so it cannot be settled yet.`
248	          : claim.proofs === 0 && ((action === 'settle' && claim.status === 'OPEN') || (action === 'approve' && claim.status === 'PENDING'))
249	            ? `This claim's due is above the proof threshold, so it needs a proof before it can be ${PAST[action]}.`
250	          : action === 'void' && claim.status === 'SETTLED'
251	            ? 'A settled claim can only be voided within 7 days of its settlement.'
252	            : `This claim cannot be ${PAST[action]} from its status.`;
253	        this.claimError.set({ id: claim.id, message });
254	      }
255	    }
256	  }
257	
258	  /** Defer an open claim until a date after the sheet's today; the store refuses a claim that is not
259	   *  OPEN, a date not after today, and a claim dated inside a closed period. */
260	  protected async defer(claim: ClaimView, until: string): Promise<void> {
261	    const sheet = this.session.sheet();
262	    if (!sheet) return;
263	    this.claimError.set(null);
264	    if (!DATE.test(until.trim())) {
265	      this.claimError.set({ id: claim.id, message: 'Type the date to defer this claim until as yyyy-mm-dd.' });
266	      return;
267	    }
268	    try {
269	      const deferred = await this.api.defer(sheet.id, claim.id, until.trim());
270	      if (this.session.sheet()?.id === sheet.id) this.changed.emit(deferred);
271	    } catch {
272	      if (this.session.sheet()?.id === sheet.id) {
273	        const message = periodOf(this.periods(), claim.date)?.closed
274	          ? 'This claim is dated inside a closed period, so it cannot be deferred.'
275	          : claim.status !== 'OPEN'
276	          ? 'Only an OPEN claim can be deferred.'
277	          : 'A claim can only be deferred to a date after the sheet\'s today.';
278	        this.claimError.set({ id: claim.id, message });
279	      }
280	    }
281	  }
282	
283	  /** Re-date an OPEN or PENDING claim; only a steward may, and the store refuses another status, a claim
284	   *  dated or a new date inside a closed period, and a new date after the person's retirement. */
285	  protected async redate(claim: ClaimView, date: string): Promise<void> {
286	    const sheet = this.session.sheet();
287	    if (!sheet) return;
288	    this.claimError.set(null);
289	    const dated = date.trim();
290	    if (!DATE.test(dated)) {
291	      this.claimError.set({ id: claim.id, message: 'Type the new date of this claim as yyyy-mm-dd.' });
292	      return;
293	    }
294	    try {
295	      const redated = await this.api.redate(sheet.id, claim.id, dated);
296	      if (this.session.sheet()?.id === sheet.id) this.changed.emit(redated);
297	    } catch (e) {
298	      if (this.session.sheet()?.id === sheet.id) {
299	        const forbidden = e instanceof HttpErrorResponse && e.status === 403;
300	        const message = forbidden
301	          ? 'Only a steward can re-date a claim.'
302	          : this.inClosedPeriod(claim.date)
303	          ? 'This claim is dated inside a closed period, so it cannot be re-dated.'
304	          : this.inClosedPeriod(dated)
305	          ? 'The new date is inside a closed period.'
306	          : !(claim.status === 'OPEN' || claim.status === 'PENDING')
307	          ? 'Only an OPEN or PENDING claim can be re-dated.'
308	          : `The new date is after ${this.personName()} retired.`;
309	        this.claimError.set({ id: claim.id, message });
310	      }
311	    }
312	  }
313	
314	  /** Raise a claim's proofs count by one; the store refuses a SETTLED or VOID claim and a claim dated
315	   *  inside a closed period. */
316	  protected async addProof(claim: ClaimView): Promise<void> {
317	    const sheet = this.session.sheet();
318	    if (!sheet) return;
319	    this.claimError.set(null);
320	    try {
321	      const proven = await this.api.addProof(sheet.id, claim.id);
322	      if (this.session.sheet()?.id === sheet.id) this.changed.emit(proven);
323	    } catch {
324	      if (this.session.sheet()?.id === sheet.id) {
325	        const message = periodOf(this.periods(), claim.date)?.closed
326	          ? 'This claim is dated inside a closed period, so no proof can be added.'
327	          : `A ${claim.status} claim cannot have a proof added.`;
328	        this.claimError.set({ id: claim.id, message });
329	      }
330	    }
331	  }
332	
333	  /** Split an amount off an OPEN claim into a new OPEN claim; the store refuses a claim that is not OPEN,
334	   *  a deferred claim, a claim dated inside a closed period, and an amount not between 0.00 and the claim's. */
335	  protected async splitClaim(claim: ClaimView, amount: string): Promise<void> {
336	    const sheet = this.session.sheet();
337	    if (!sheet) return;
338	    this.claimError.set(null);
339	    const part = amount.trim();
340	    if (!/^\d+(\.\d{1,2})?$/.test(part) || Number(part) <= 0) {
341	      this.claimError.set({ id: claim.id, message: 'Type an amount to split off, more than 0.00 and less than the claim\'s.' });
342	      return;
343	    }
344	    try {
345	      const split = await this.api.split(sheet.id, claim.id, part);
346	      if (this.session.sheet()?.id === sheet.id) this.split.emit(split);
347	    } catch {
348	      if (this.session.sheet()?.id === sheet.id) {
349	        const message = periodOf(this.periods(), claim.date)?.closed
350	          ? 'This claim is dated inside a closed period, so it cannot be split.'
351	          : claim.status !== 'OPEN'
352	          ? 'Only an OPEN claim can be split.'
353	          : this.deferred(claim)
354	          ? `This claim is deferred until ${claim.deferredUntil}, so it cannot be split.`
355	          : 'The amount split off must be more than 0.00 and less than the claim\'s amount.';
356	        this.claimError.set({ id: claim.id, message });
357	      }
358	    }
359	  }
360	
361	  /** Move a draft, open or pending claim to the chosen person; only a role the permission matrix allows may. */
362	  protected async reassign(claim: ClaimView, to: string): Promise<void> {
363	    const sheet = this.session.sheet();
364	    if (!sheet) return;
365	    this.claimError.set(null);
366	    if (to === '') {
367	      this.claimError.set({ id: claim.id, message: 'Choose the person to move this claim to.' });
368	      return;
369	    }
370	    try {
371	      const moved = await this.api.reassign(sheet.id, claim.id, Number(to));
372	      if (this.session.sheet()?.id === sheet.id) {
373	        if (this.editingId() === claim.id) this.reset();
374	        this.reassigned.emit(moved);
375	      }
376	    } catch (e) {
377	      if (this.session.sheet()?.id === sheet.id) {
378	        const forbidden = e instanceof HttpErrorResponse && e.status === 403;
379	        const message = forbidden
380	          ? 'Your role may not move a claim to another person on this sheet.'
381	          : periodOf(this.periods(), claim.date)?.closed
382	          ? 'This claim is dated inside a closed period, so it cannot be moved.'
383	          : 'This claim cannot be moved to that person; a settled or voided claim cannot move.';
384	        this.claimError.set({ id: claim.id, message });
385	      }
386	    }
387	  }
388	
389	  protected cancel(): void {
390	    this.reset();
391	  }
392	
393	  protected async submit(): Promise<void> {
394	    // A second submit before the first has answered is ignored, so it stores one record, not two.
395	    if (this.saving()) return;
396	    const sheet = this.session.sheet();
397	    if (!sheet) return;
398	    this.error.set('');
399	    this.claimError.set(null);
400	    const value = this.form.getRawValue();
401	    const amount = value.amount.trim();
402	    const date = value.date.trim();
403	    const corrects = value.corrects.trim();
404	    if (!CLAIM_AMOUNT.test(amount)) {
405	      this.error.set('Type an amount with up to two decimals; a negative amount is a correction.');
406	      return;
407	    }
408	    const correction = amount.startsWith('-') && Number(amount) !== 0;
409	    if (correction && !CLAIM_NUMBER.test(corrects)) {
410	      this.error.set('A negative amount is a correction: type the number of the settled claim it corrects.');
411	      return;
412	    }
413	    if (date !== '' && !DATE.test(date)) {
414	      this.error.set('Type a date as yyyy-mm-dd.');
415	      return;
416	    }
417	    const form = { amount, date: date === '' ? null : date, note: value.note.trim(),
418	      corrects: correction ? corrects : null };
419	    const id = this.editingId();
420	    this.saving.set(true);
421	    try {
422	      if (id === null) {
423	        const claim = await this.api.add(sheet.id, this.personId(), form);
424	        if (this.session.sheet()?.id === sheet.id) this.added.emit(claim);
425	      } else {
426	        const claim = await this.api.update(sheet.id, id, form);
427	        if (this.session.sheet()?.id === sheet.id) this.saved.emit(claim);
428	      }
429	      if (this.session.sheet()?.id === sheet.id) this.reset();
430	    } catch (e) {
431	      const conflict = e instanceof HttpErrorResponse && e.status === 409;
432	      const uncorrected = e instanceof HttpErrorResponse && e.status === 422;
433	      const editing = id === null ? undefined : this.claims().find((c) => c.id === id);
434	      if (conflict && editing && !this.inClosedPeriod(editing.date) && !this.inClosedPeriod(date)) {
435	        // Only a draft can be edited; the refusal is shown on the claim, and the editor stays open.
436	        this.claimError.set({ id: editing.id, message: 'Only a draft claim can be edited. To change an open claim, void it and add a new one.' });
437	      } else {
438	        this.error.set(uncorrected
439	          ? 'A correction must name, by number, a settled claim of this person.'
440	          : conflict
441	          ? 'A claim dated inside a closed period cannot be added or changed.'
442	          : id === null ? 'The claim could not be added.' : 'The claim could not be saved.');
443	      }
444	    } finally {
445	      this.saving.set(false);
446	    }
447	  }
448	}
